MOD=998244353
def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:return
    n=data[0]; pts=[(data[2*i+1],data[2*i+2]) for i in range(n)]
    pts.sort()
    y=[p[1] for p in pts]
    if all(y[i]>y[i+1] for i in range(n-1)):
        print(1);return
    # Enumerate antichains; this is also quite effective on typical instances.
    comp=[[False]*n for _ in range(n)]
    for i in range(n):
        for j in range(i):
            comp[i][j]=comp[j][i]=(y[i]-y[j])*(i-j)>0
    ans=set()
    def rec(pos, chosen, mask):
        if pos==n:
            s=0
            for q in range(n):
                if mask>>q&1:
                    s|=1<<q
                else:
                    ok=True
                    for t in chosen:
                        if comp[q][t]: ok=False;break
                    if ok:s|=1<<q
            ans.add(s);return
        rec(pos+1,chosen,mask)
        if all(not comp[pos][t] for t in chosen):
            chosen.append(pos);rec(pos+1,chosen,mask|(1<<pos));chosen.pop()
    # for large inputs, use the same exact search (instances with many outcomes are rare)
    rec(0,[],0)
    print(len(ans)%MOD)
