def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]
    mx = max(a)

    phi = list(range(mx + 1))
    for p in range(2, mx + 1):
        if phi[p] == p:
            for v in range(p, mx + 1, p):
                phi[v] -= phi[v] // p

    divisors = [[] for _ in range(mx + 1)]
    for d in range(1, mx + 1):
        for v in range(d, mx + 1, d):
            divisors[v].append(d)

    stored = [0] * (mx + 1)
    answer = 0
    weight = 1
    output = []

    for x in a:
        total = 0
        for d in divisors[x]:
            total += phi[d] * stored[d]
        answer = (answer * 2 + total) % MOD
        output.append(str(answer))
        for d in divisors[x]:
            stored[d] = (stored[d] + weight) % MOD
        weight = (weight * 2) % MOD

    sys.stdout.write('\n'.join(output))

if __name__ == '__main__':
    main()

