def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:return
    n,q=data[0],data[1]; p=list(range(n)); sz=[1]*n; lo=list(range(n)); hi=list(range(n)); col=list(range(1,n+1)); cnt=[0]+[1]*n
    def find(a):
        while p[a]!=a:
            p[a]=p[p[a]]; a=p[a]
        return a
    def union(a,b):
        a=find(a); b=find(b)
        if a==b:return a
        if sz[a]<sz[b]:a,b=b,a
        p[b]=a; sz[a]+=sz[b]; lo[a]=min(lo[a],lo[b]); hi[a]=max(hi[a],hi[b])
        return a
    out=[]; k=2
    for _ in range(q):
        t=data[k];k+=1
        if t==1:
            x=data[k]-1;c=data[k+1];k+=2
            r=find(x); old=col[r]; s=sz[r]
            cnt[old]-=s;cnt[c]+=s;col[r]=c
            if lo[r]>0:
                z=find(lo[r]-1)
                if col[z]==c:r=union(r,z)
