from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        ending = [[] for _ in range(n + 1)]
        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            ending[b].append((a, idx))

        # Among pairs whose larger endpoint has been reached, maintain the
        # largest and second-largest smaller endpoints.  A subarray ending at
        # r must start after the largest such endpoint.
        largest = 0
        second = 0
        largest_count = 0
        largest_id = -1
        gain = [0] * len(conflictingPairs)
        total = 0

        for r in range(1, n + 1):
            for a, idx in ending[r]:
                if a > largest:
                    second = largest
                    largest = a
                    largest_count = 1
                    largest_id = idx
                elif a == largest:
                    largest_count += 1
                    largest_id = -1
                elif a > second:
                    second = a

            total += r - largest
            if largest_count == 1:
                gain[largest_id] += largest - second

        return total + max(gain)

