import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    p = 0
    n, m, q = data[p], data[p+1], data[p+2]
    p += 3
    edges = []
    for _ in range(m):
        a, b, c = data[p]-1, data[p+1]-1, data[p+2]
        p += 3
        edges.append((a, b, c))
    queries = []
    closed = set()
    for _ in range(q):
        t = data[p]
        p += 1
        if t == 1:
            e = data[p]-1
            p += 1
            queries.append((1, e))
            closed.add(e)
        else:
            x, y = data[p]-1, data[p+1]-1
            p += 2
            queries.append((2, x, y))

    INF = 10**30
    dist = [[INF] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for e, (a, b, c) in enumerate(edges):
        if e not in closed:
            dist[a][b] = c
            dist[b][a] = c

    for k in range(n):
        rk = dist[k]
        for i in range(n):
            dik = dist[i][k]
            if dik == INF:
                continue
            ri = dist[i]
            for j in range(n):
                v = dik + rk[j]
                if v < ri[j]:
                    ri[j] = v

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
            v = dist[query[1]][query[2]]
            answers.append(str(v if v < INF else -1))
        else:
            a, b, w = edges[query[1]]
            ra, rb = dist[a], dist[b]
            for i in range(n):
                ri = dist[i]
                x = ri[a] + w
                y = ri[b] + w
                for j in range(n):
                    v = x + rb[j]
                    z = y + ra[j]
                    if z < v:
                        v = z
                    if v < ri[j]:
                        ri[j] = v
    sys.stdout.write('\n'.join(reversed(answers)))

if __name__ == '__main__':
    main()

