class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        length = len(s)

        comb = [[0] * (length + 1) for _ in range(length + 1)]
        for i in range(length + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        good = [False] * (length + 1)
        for ones in range(1, length + 1):
            value = ones
            operations = 0
            while value != 1:
                value = value.bit_count()
                operations += 1
            good[ones] = operations <= k - 1

        answer = 0
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = length - i - 1
                for total_ones in range(1, length + 1):
                    needed = total_ones - prefix_ones
                    if good[total_ones] and 0 <= needed <= remaining:
                        answer = (answer + comb[remaining][needed]) % MOD
                prefix_ones += 1

        return answer

