class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        C = [[0]*(n+1) for _ in range(n+1)]
        for i in range(n+1):
            C[i][0] = C[i][i] = 1
            for j in range(1, i):
                C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD
        good = [False]*(n+1)
        for j in range(1, n+1):
            x, steps = j, 0
            while x != 1:
                x = x.bit_count()
                steps += 1
            good[j] = steps <= k-1
        ans = 0
        pref = 0
        for i, ch in enumerate(s):
