class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        used = [False] * (n + 1)
        odd = (n + 1) // 2
        even = n // 2

        def ways(o: int, e: int, required: int) -> int:
            if required == 1:
                if not (o == e or o == e + 1):
                    return 0
            else:
                if not (e == o or e == o + 1):
                    return 0
            return fact[o] * fact[e]

        answer = []
        previous_parity = None

        for position in range(n):
            for value in range(1, n + 1):
                parity = value & 1
                if used[value] or (previous_parity is not None and parity == previous_parity):
                    continue

                remaining_odd = odd - parity
                remaining_even = even - (1 - parity)
                if position == n - 1:
                    block = 1
