class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        weights = []
        for i in range(m):
            j = n - 1 - i
            if i == j:
                weights.append(powers[i])
            else:
                weights.append((powers[i] + powers[j]) % k)

        # dp[i][r] indicates whether positions i onward can contribute r mod k.
        dp = [None] * (m + 1)
        dp[m] = bytearray(k)
        dp[m][0] = 1
        for i in range(m - 1, -1, -1):
            row = bytearray(k)
            nxt = dp[i + 1]
            weight = weights[i]
            for r in range(k):
                if nxt[r]:
                    for digit in range(10):
                        row[(r + digit * weight) % k] = 1
            dp[i] = row

        left = []
        remainder = 0
        for i, weight in enumerate(weights):
            lowest = 1 if i == 0 else 0
            for digit in range(9, lowest - 1, -1):
                new_remainder = (remainder + digit * weight) % k
                if dp[i + 1][(-new_remainder) % k]:
                    left.append(str(digit))
                    remainder = new_remainder
                    break

        half = ''.join(left)
        if n % 2:
            return half + half[-2::-1]
        return half + half[::-1]

