from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        from array import array
        n = len(nums)
        ng = [n] * n
        stack = []
        for i, x in enumerate(nums):
            while stack and nums[stack[-1]] <= x:
                ng[stack.pop()] = i
            stack.append(i)

        levels = n.bit_length()
        jump = [array('i', ng)]
        sums = [array('q', (nums[i] * (ng[i] - i) for i in range(n)))]
        for _ in range(1, levels):
            oldj, olds = jump[-1], sums[-1]
            nj = array('i', [0]) * n
            ns = array('q', [0]) * n
            for i in range(n):
                q = oldj[i]
                if q < n:
                    nj[i] = oldj[q]
                    ns[i] = olds[i] + olds[q]
                else:
                    nj[i] = n
                    ns[i] = olds[i]
            jump.append(nj)
            sums.append(ns)

        prefix = [0]
        for x in nums:
            prefix.append(prefix[-1] + x)

        def cost(left, right):
            p = left
            total = 0
            for z in range(levels - 1, -1, -1):
                q = jump[z][p]
                if q <= right:
                    total += sums[z][p]
                    p = q
            total += nums[p] * (right - p + 1)
            return total - (prefix[right + 1] - prefix[left])

        answer = 0
        for right in range(n):
            lo, hi = 0, right
            while lo < hi:
                mid = (lo + hi) // 2
                if cost(mid, right) <= k:
                    hi = mid
                else:
                    lo = mid + 1
            answer += right - lo + 1
        return answer

