import sys
from functools import cmp_to_key

def main():
    input = sys.stdin.readline
    N, K = map(int, input().split())
    funcs = [tuple(map(int, input().split())) for _ in range(N)]

    # Functions are applied in ascending order of (A-1)/B.
    def compare(f, g):
        left = (f[0] - 1) * g[1]
        right = (g[0] - 1) * f[1]
        return (left > right) - (left < right)

    funcs.sort(key=cmp_to_key(compare))

    dp = [-1] * (K + 1)
    dp[0] = 1
    for a, b in funcs:
        for count in range(K, 0, -1):
            if dp[count - 1] != -1:
                dp[count] = max(dp[count], a * dp[count - 1] + b)

    print(dp[K])

if __name__ == "__main__":
    main()

