class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        parent = [-1] * n
        order = [0]
        for u in order:
            for v, w in graph[u]:
                if v != parent[u]:
                    parent[v] = u
                    order.append(v)

        # dp0[u]: best subtree value when the parent edge is not used
        # dp1[u]: best subtree value when the parent edge is used
        dp0 = [0] * n
        dp1 = [0] * n

        for u in reversed(order):
            base = 0
            gains = []
            for v, w in graph[u]:
                if parent[v] == u:
                    base += dp0[v]
                    gains.append(w + dp1[v] - dp0[v])

            gains.sort(reverse=True)

            value = base
            for gain in gains[:k]:
                if gain > 0:
                    value += gain
            dp0[u] = value

            value = base
            for gain in gains[:max(0, k - 1)]:
                if gain > 0:
                    value += gain
            dp1[u] = value

        return dp0[0]

