import sys
from functools import lru_cache

sys.setrecursionlimit(1_000_000)

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m, l = data[:3]
    values = data[3:]
    total = n + m + l
    all_mask = (1 << total) - 1

    @lru_cache(maxsize=None)
    def winning(a, b, turn):
        hand = a if turn == 0 else b
        if hand == 0:
            return False
        table = all_mask ^ a ^ b
        remaining = hand
        while remaining:
            bit = remaining & -remaining
            remaining -= bit
            i = bit.bit_length() - 1

            if turn == 0:
                after_a, after_b = a ^ bit, b
            else:
                after_a, after_b = a, b ^ bit

            # Play the card without taking anything.
            if not winning(after_a, after_b, 1 - turn):
                return True

            # Or take any smaller card currently on the table.
            candidates = table
            while candidates:
                take = candidates & -candidates
                candidates -= take
                j = take.bit_length() - 1
                if values[j] < values[i]:
                    if turn == 0:
                        if not winning(after_a | take, after_b, 1):
                            return True
                    else:
                        if not winning(after_a, after_b | take, 0):
                            return True
        return False

    initial_a = (1 << n) - 1
    initial_b = ((1 << m) - 1) << n
    print("Takahashi" if winning(initial_a, initial_b, 0) else "Aoki")

if __name__ == "__main__":
    main()

