import sys
import heapq

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    g = [[] for _ in range(n)]
    j = 1
    for _ in range(n - 1):
        u, v, w = data[j] - 1, data[j + 1] - 1, data[j + 2]
        j += 3
        g[u].append((v, w))
        g[v].append((u, w))

    parent = [-1] * n
    order = [0]
    for x in order:
        for y, w in g[x]:
            if y != parent[x]:
                parent[y] = x
                order.append(y)

    down = [0] * n
    best_child = [-1] * n
    for x in reversed(order):
        for y, w in g[x]:
            if parent[y] == x and w + down[y] > down[x]:
                down[x] = w + down[y]
                best_child[x] = y

    # A heap entry is an uncovered child subtree.  Its key is the
    # maximum additional distance obtainable by choosing one vertex there.
    heap = []
    for y, w in g[0]:
        if parent[y] == 0:
            heapq.heappush(heap, (-(w + down[y]), y))

    total = 0
    out = []
    for _ in range(n):
        if heap:
            gain, x = heapq.heappop(heap)
            total -= gain
            # Follow a longest downward path.  Every side branch becomes
            # an independent still-uncovered subtree.
            while True:
                nxt = best_child[x]
                for y, w in g[x]:
                    if parent[y] == x and y != nxt:
                        heapq.heappush(heap, (-(w + down[y]), y))
                if nxt == -1:
                    break
                x = nxt
        out.append(str(2 * total))
    sys.stdout.write("\n".join(out))

if __name__ == '__main__':
    main()

