    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    graph = [[] for _ in range(n)]
    pos = 2
    for _ in range(m):
        x = data[pos] - 1
        y = data[pos + 1] - 1
        z = data[pos + 2]
        pos += 3
        graph[x].append((y, z))
        graph[y].append((x, z))

    label = [-1] * n
    answer = [0] * n

    for start in range(n):
        if label[start] != -1:
            continue
        label[start] = 0
        stack = [start]
        component = []
        consistent = True

        while stack:
            v = stack.pop()
            component.append(v)
            for u, z in graph[v]:
                required = label[v] ^ z
                if label[u] == -1:
                    label[u] = required
                    stack.append(u)
                elif label[u] != required:
                    consistent = False

        if not consistent:
            print(-1)
            return

        ones = [0] * 30
        for v in component:
            value = label[v]
            for bit in range(30):
                ones[bit] += (value >> bit) & 1

        size = len(component)
        shift = 0
        for bit in range(30):
            if ones[bit] > size - ones[bit]:
                shift |= 1 << bit
        for v in component:
            answer[v] = label[v] ^ shift

    print(*answer)

