import sys


def possible(a, b, k):
    m = len(a)
    q = len(b)
    j = 0

    for i, x in enumerate(a):
        while j < q and abs(x - b[j]) > k:
            j += 1

        if j == q:
            return False

        # If every remaining piece must occupy a different remaining
        # target square, reserve the next target for the next piece.
        if m - i == q - j:
            j += 1

    return j == q


def solve_case(n, a_str, b_str):
    a = [i for i, c in enumerate(a_str) if c == "1"]
    b = [i for i, c in enumerate(b_str) if c == "1"]

    if len(a) < len(b):
        return -1

    lo, hi = 0, n - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if possible(a, b, mid):
            hi = mid
        else:
            lo = mid + 1

    return lo if possible(a, b, lo) else -1


