from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        # Generate the postorder iteratively, avoiding recursion depth issues.
        stack = [(0, 0)]
        postorder = []
        while stack:
            u, exiting = stack.pop()
            if not exiting:
                stack.append((u, 1))
                for v in reversed(children[u]):
                    stack.append((v, 0))
            else:
                postorder.append(u)

        sequence = []
        end = [0] * n
        size = [0] * n
        for u in postorder:
            end[u] = len(sequence)
            sequence.append(s[u])
            size[u] = 1 + sum(size[v] for v in children[u])

        # Manacher radii for odd-length palindromes.
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
