import sys

def main():
    N = int(sys.stdin.readline())

    # M is floor(sqrt(N)); products of two distinct primes must not exceed M.
    M = int(N ** 0.5)
    while (M + 1) * (M + 1) <= N:
        M += 1
    while M * M > N:
        M -= 1

    is_prime = bytearray(b'\x01') * (M + 1)
    if M >= 0:
        is_prime[0] = 0
    if M >= 1:
        is_prime[1] = 0
    for p in range(2, int(M ** 0.5) + 1):
        if is_prime[p]:
            start = p * p
            is_prime[start:M + 1:p] = b'\x00' * (((M - start) // p) + 1)

    primes = [p for p in range(2, M + 1) if is_prime[p]]

    # Numbers p^8 have (8+1) divisors.
    answer = sum(p ** 8 <= N for p in primes)

    # Numbers (p*q)^2, for distinct primes p,q, have 9 divisors.
    right = len(primes) - 1
    for left, p in enumerate(primes):
        if p * p > M:
            break
        while right > left and p * primes[right] > M:
            right -= 1
        if right <= left:
            break
        answer += right - left

    print(answer)

if __name__ == '__main__':
    main()

