class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return 0

        # Li Chao tree storing lines y = slope*x + intercept.
        size = 4 * n
        slopes = [0] * size
        intercepts = [0] * size
        present = [False] * size

        def val(k, x):
            return slopes[k] * x + intercepts[k]

        def add(k, left, right, slope, intercept):
            if not present[k]:
                present[k] = True
                slopes[k] = slope
                intercepts[k] = intercept
                return

            mid = (left + right) // 2
            if val(k, mid) < slope * mid + intercept:
                slopes[k], slope = slope, slopes[k]
                intercepts[k], intercept = intercept, intercepts[k]

            if left == right:
                return
            if slope * left + intercept > val(k, left):
                add(k * 2, left, mid, slope, intercept)
            elif slope * right + intercept > val(k, right):
                add(k * 2 + 1, mid + 1, right, slope, intercept)

        def query(k, left, right, x):
            if not present[k]:
                return -10**30
            result = val(k, x)
            if left == right:
                return result
            mid = (left + right) // 2
            if x <= mid:
                return max(result, query(k * 2, left, mid, x))
            return max(result, query(k * 2 + 1, mid + 1, right, x))

        add(1, 1, n - 1, nums[0], 0)
        answer = 0
        for j in range(1, n):
            dp = query(1, 1, n - 1, j)
            answer = dp
            add(1, 1, n - 1, nums[j], dp - j * nums[j])
        return answer

