from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        if all(x == 0 for x in nums):
            return 0

        # dp[i]'s bits represent the sums attainable at index i using
        # the queries processed so far.
        dp = [1] * n  # sum 0 is initially attainable

        for k, (left, right, value) in enumerate(queries, 1):
            for i in range(left, right + 1):
                dp[i] |= dp[i] << value
                # Sums larger than the required value are irrelevant.
                dp[i] &= (1 << (nums[i] + 1)) - 1

            if all((dp[i] >> nums[i]) & 1 for i in range(n)):
                return k

        return -1

