import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        digits = len(str(n))
        low = 10 ** (digits - 1)
        high = 10 ** digits - 1

        is_prime = [True] * (high + 1)
        is_prime[0] = is_prime[1] = False
        for p in range(2, int(high ** 0.5) + 1):
            if is_prime[p]:
                for x in range(p * p, high + 1, p):
                    is_prime[x] = False

        if is_prime[n] or is_prime[m]:
            return -1
        if n == m:
            return n

        powers = [10 ** i for i in range(digits)]
        distance = {n: n}
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != distance.get(value):
                continue
            if value == m:
                return cost

            for power in powers:
                digit = (value // power) % 10
                if digit < 9:
                    nxt = value + power
                    if nxt <= high and not is_prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < distance.get(nxt, float('inf')):
                            distance[nxt] = new_cost
                            heapq.heappush(heap, (new_cost, nxt))
                if digit > 0:
                    nxt = value - power
                    if nxt >= low and not is_prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < distance.get(nxt, float('inf')):
                            distance[nxt] = new_cost
                            heapq.heappush(heap, (new_cost, nxt))

        return -1

