from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        # z[i] is the length of the longest common prefix of nums and nums[i:].
        z = [0] * n
        if n:
            z[0] = n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        answer = 0
        # d is the length of the middle subarray; i is the first boundary.
        # For each fixed d, calculate LCP(i, i+d) backwards using its recurrence.
        for d in range(1, n):
            common = 0
            for i in range(n - d - 1, 0, -1):
                if nums[i] == nums[i + d]:
                    common += 1
                else:
                    common = 0

                # nums1 is a prefix of nums2, or nums2 is a prefix of nums3.
                if (d >= i and z[i] >= i) or common >= d:
                    answer += 1

        return answer

