                            if prev_right == right_color:
                                continue
                            best_previous = min(best_previous, dp[prev_left][prev_right])
                    ndp[left_color][right_color] = (
                        best_previous
                        + cost[i][left_color]
                        + cost[n - 1 - i][right_color]
                    )
            dp = ndp

        return min(min(row) for row in dp)

