class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        def at_most(limit: int) -> int:
            if limit < 0:
                return 0
            last = {v: -1 for v in "aeiou"}
            left = consonants = result = 0
            for right, ch in enumerate(word):
                if ch in last:
                    last[ch] = right
                else:
                    consonants += 1
                while consonants > limit:
                    if word[left] not in last:
                        consonants -= 1
                    left += 1
                earliest_last_vowel = min(last.values())
                if earliest_last_vowel >= left:
                    result += earliest_last_vowel - left + 1
            return result

        return at_most(k) - at_most(k - 1)

